update public.exams e
   set title = 'MYP2 Mathematics — Mock Examination',
       description = 'Grade 7 · MYP 2 · Mathematics · Mock Examination. Ratio, rate and proportion, set theory and Venn diagrams, probability. 45 questions, 189 marks: Section A (objective) and Section B (structured, constructed responses). Full marking schemes, three-level hints and question-level feedback.',
       instructions = 'MYP2 MATHEMATICS — MOCK EXAMINATION (Grade 7)

Time allowed: 2 hours 30 minutes.

SECTION A — Objective questions (questions 1–22).
Each question has one correct answer (or, where stated, more than one). For numeric questions type the value only, without units. Read every stem: several questions give you data you must interpret before you calculate.

SECTION B — Structured questions (questions 23–45).
Write your working and type each part''s answer in its own box. Marks are shown beside every part, so you can see how much detail a part needs. Where a question shows a table, graph or Venn diagram workspace, build the representation there — that is what is being assessed. A fully correct answer with no supportable method may lose method marks.

EXAMINATION OBJECTIVES. By the end of this paper you should be able to: use ratio and rate to compare and scale quantities, including best-buy and speed problems; share quantities in a given ratio and decide when a proportional relationship is direct, inverse or neither; use set notation and construct two- and three-set Venn diagrams; calculate and compare theoretical and experimental probabilities; and explain your reasoning in clear mathematical language.

GENERAL INSTRUCTIONS.
1. Calculators are not permitted. Show all necessary working; no marks are given for an answer alone in Section B unless a part says so.
2. Give units with every answer that has one, and simplify all fractions and ratios.
3. A hint is available on every part. Hints guide your thinking and never reveal the answer; using one costs no marks and is recorded only to help you revise.
4. Your answers save automatically. If your connection drops, reopen the paper and your work is restored exactly as you left it.
5. Do not write only a final answer for a part that asks you to explain, justify or describe: those parts are marked on the reasoning.

MARKS. Every part shows its own marks, and the totals for each section are printed on the cover: Section A is worth 55 marks and Section B is worth 134 marks, out of a total of 189. Pass mark: your institution''s configured threshold (default 50%).',
       duration_minutes = 150,
       settings = coalesce(e.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"7","curriculum":"MYP 2","subject":"Mathematics","total_marks":189,"source":"myp-mock-myp2-mock","mock_exam_key":"myp2-mock","mock_code":"MYP2-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb
 where e.id = 'd2000000-0000-4000-8000-000000000002'::uuid
   and e.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   and (
     e.title is distinct from 'MYP2 Mathematics — Mock Examination'
     or e.description is distinct from 'Grade 7 · MYP 2 · Mathematics · Mock Examination. Ratio, rate and proportion, set theory and Venn diagrams, probability. 45 questions, 189 marks: Section A (objective) and Section B (structured, constructed responses). Full marking schemes, three-level hints and question-level feedback.'
     or e.instructions is distinct from 'MYP2 MATHEMATICS — MOCK EXAMINATION (Grade 7)

Time allowed: 2 hours 30 minutes.

SECTION A — Objective questions (questions 1–22).
Each question has one correct answer (or, where stated, more than one). For numeric questions type the value only, without units. Read every stem: several questions give you data you must interpret before you calculate.

SECTION B — Structured questions (questions 23–45).
Write your working and type each part''s answer in its own box. Marks are shown beside every part, so you can see how much detail a part needs. Where a question shows a table, graph or Venn diagram workspace, build the representation there — that is what is being assessed. A fully correct answer with no supportable method may lose method marks.

EXAMINATION OBJECTIVES. By the end of this paper you should be able to: use ratio and rate to compare and scale quantities, including best-buy and speed problems; share quantities in a given ratio and decide when a proportional relationship is direct, inverse or neither; use set notation and construct two- and three-set Venn diagrams; calculate and compare theoretical and experimental probabilities; and explain your reasoning in clear mathematical language.

GENERAL INSTRUCTIONS.
1. Calculators are not permitted. Show all necessary working; no marks are given for an answer alone in Section B unless a part says so.
2. Give units with every answer that has one, and simplify all fractions and ratios.
3. A hint is available on every part. Hints guide your thinking and never reveal the answer; using one costs no marks and is recorded only to help you revise.
4. Your answers save automatically. If your connection drops, reopen the paper and your work is restored exactly as you left it.
5. Do not write only a final answer for a part that asks you to explain, justify or describe: those parts are marked on the reasoning.

MARKS. Every part shows its own marks, and the totals for each section are printed on the cover: Section A is worth 55 marks and Section B is worth 134 marks, out of a total of 189. Pass mark: your institution''s configured threshold (default 50%).'
     or e.duration_minutes is distinct from 150
     or e.settings is distinct from (coalesce(e.settings, '{}'::jsonb) || '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"7","curriculum":"MYP 2","subject":"Mathematics","total_marks":189,"source":"myp-mock-myp2-mock","mock_exam_key":"myp2-mock","mock_code":"MYP2-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb)
   );

do $$
declare
  v_questions integer;
  v_options integer;
  v_paper_rows integer;
  v_hints integer;
begin
  select count(*) into v_questions
    from _myp_mock_forward_stage s
    join public.questions q on q.id = s.question_id
   where q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
     and q.type = s.question_type
     and q.prompt = s.prompt
     and q.prompt_doc = s.prompt_doc
     and q.explanation = s.explanation
     and q.explanation_doc is null
     and q.points = s.points
     and q.difficulty = s.difficulty
     and q.topic = s.topic
     and q.subtopic = s.subtopic
     and q.config = s.config;
  if v_questions <> 45 then
    raise exception 'MYP2-MOCK-2026: only % question rows match the authored forward payload after update', v_questions;
  end if;

  select count(*) into v_options
    from _myp_mock_forward_options d
    join public.question_options o
      on o.question_id = d.question_id and o.position = d.position
   where o.label = d.label and o.is_correct = d.is_correct and o.content_doc is null;
  if v_options <> (select count(*) from _myp_mock_forward_options) then
    raise exception 'MYP2-MOCK-2026: option rows did not reconcile to the authored payload';
  end if;

  select count(*) into v_paper_rows
    from _myp_mock_forward_stage s
    join public.quiz_questions qq
      on qq.quiz_id = 'd2000000-0000-4000-8000-000000000001'::uuid and qq.question_id = s.question_id
   where qq.position = s.question_number and qq.points = s.points;
  if v_paper_rows <> 45 then
    raise exception 'MYP2-MOCK-2026: only % quiz-question rows match the authored order and marks', v_paper_rows;
  end if;

  select count(*) into v_hints
    from _myp_mock_forward_hints d
    join public.question_hints h
      on h.exam_id = 'd2000000-0000-4000-8000-000000000002'::uuid and h.question_id = d.question_id and h.level = d.level
   where h.body = d.body and h.status = 'published';
  if v_hints <> (select count(*) from _myp_mock_forward_hints) then
    raise exception 'MYP2-MOCK-2026: only % authored hint rows were reconciled', v_hints;
  end if;

  if not exists (
    select 1 from public.quizzes q
     where q.id = 'd2000000-0000-4000-8000-000000000001'::uuid and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and q.settings @> '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"7","curriculum":"MYP 2","subject":"Mathematics","total_marks":189,"source":"myp-mock-myp2-mock","mock_exam_key":"myp2-mock","mock_code":"MYP2-MOCK-2026","duration_minutes":150,"sections":[{"id":"A","title":"Section A — Objective","questions":22,"marks":55,"instructions":"One correct answer per question. The options are written so a wrong choice identifies a specific misconception."},{"id":"B","title":"Section B — Structured","questions":23,"marks":134,"instructions":"Show your working. Every part carries its own marks, its own answer box and its own two hints."}]}'::jsonb
  ) then
    raise exception 'MYP2-MOCK-2026: quiz metadata did not reconcile';
  end if;
  if not exists (
    select 1 from public.exams e
     where e.id = 'd2000000-0000-4000-8000-000000000002'::uuid and e.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
       and e.duration_minutes = 150
       and e.settings @> '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"7","curriculum":"MYP 2","subject":"Mathematics","total_marks":189,"source":"myp-mock-myp2-mock","mock_exam_key":"myp2-mock","mock_code":"MYP2-MOCK-2026","show_sections":true,"feedback":{"marking_criteria":true,"next_time_hint":true,"objective_structured_split":true,"topic_breakdown":true,"criterion_level_band":true}}'::jsonb
  ) then
    raise exception 'MYP2-MOCK-2026: examination metadata did not reconcile';
  end if;
end $$;

commit;
